2848	    mstime_t latency;
2849	    int del_flag = notify_type == NOTIFY_EXPIRED ? DB_FLAG_KEY_EXPIRED : DB_FLAG_KEY_EVICTED;
2850	    int lazy_flag = notify_type == NOTIFY_EXPIRED ? server.lazyfree_lazy_expire : server.lazyfree_lazy_eviction;
2851	    char *latency_name = notify_type == NOTIFY_EXPIRED ? "expire-del" : "evict-del";
2852	    char *notify_name = notify_type == NOTIFY_EXPIRED ? "expired" : "evicted";
2853	
